//! Pure ISO 8601 calendar / clock arithmetic for Temporal (no VM access).
//!
//! Dates are proleptic Gregorian; epoch nanoseconds and time durations are
//! exact `i128` values.

use std::cmp::Ordering;

pub const NS_PER_SECOND: i128 = 1_000_000_000;
pub const NS_PER_MINUTE: i128 = 60 * NS_PER_SECOND;
pub const NS_PER_HOUR: i128 = 60 * NS_PER_MINUTE;
pub const NS_PER_DAY: i128 = 24 * NS_PER_HOUR;
/// nsMaxInstant = 10^8 days
pub const NS_MAX_INSTANT: i128 = 8_640_000_000_000_000_000_000;
pub const NS_MIN_INSTANT: i128 = -NS_MAX_INSTANT;
/// maxTimeDuration = 2^53 × 10^9 − 1
pub const MAX_TIME_DURATION: i128 = 9_007_199_254_740_992 * NS_PER_SECOND - 1;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub struct IsoDate {
    pub year: i64,
    pub month: u8,
    pub day: u8,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Default, Hash)]
pub struct Time {
    pub hour: u8,
    pub minute: u8,
    pub second: u8,
    pub millisecond: u16,
    pub microsecond: u16,
    pub nanosecond: u16,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub struct IsoDateTime {
    pub date: IsoDate,
    pub time: Time,
}

impl IsoDate {
    pub fn new(year: i64, month: u8, day: u8) -> IsoDate {
        IsoDate { year, month, day }
    }
}

impl Time {
    pub const MIDNIGHT: Time = Time { hour: 0, minute: 0, second: 0, millisecond: 0, microsecond: 0, nanosecond: 0 };
    pub const NOON: Time = Time { hour: 12, minute: 0, second: 0, millisecond: 0, microsecond: 0, nanosecond: 0 };

    /// Nanoseconds since midnight.
    pub fn to_ns(&self) -> i128 {
        (((self.hour as i128 * 60 + self.minute as i128) * 60 + self.second as i128) * 1000 + self.millisecond as i128)
            * 1_000_000
            + self.microsecond as i128 * 1000
            + self.nanosecond as i128
    }

    /// Balance a (possibly negative / overflowing) count of nanoseconds since
    /// midnight into (days, time).
    pub fn balance(ns: i128) -> (i64, Time) {
        let days = ns.div_euclid(NS_PER_DAY);
        let mut r = ns.rem_euclid(NS_PER_DAY);
        let nanosecond = (r % 1000) as u16;
        r /= 1000;
        let microsecond = (r % 1000) as u16;
        r /= 1000;
        let millisecond = (r % 1000) as u16;
        r /= 1000;
        let second = (r % 60) as u8;
        r /= 60;
        let minute = (r % 60) as u8;
        r /= 60;
        let hour = r as u8;
        (days as i64, Time { hour, minute, second, millisecond, microsecond, nanosecond })
    }

    pub fn sub_second_ns(&self) -> u32 {
        self.millisecond as u32 * 1_000_000 + self.microsecond as u32 * 1000 + self.nanosecond as u32
    }
}

pub fn is_leap(y: i64) -> bool {
    y.rem_euclid(4) == 0 && (y.rem_euclid(100) != 0 || y.rem_euclid(400) == 0)
}

pub fn days_in_month(y: i64, m: u8) -> u8 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => 30,
    }
}

pub fn days_in_year(y: i64) -> u16 {
    if is_leap(y) {
        366
    } else {
        365
    }
}

/// Days since 1970-01-01 (the date must be balanced).
pub fn epoch_days(d: IsoDate) -> i64 {
    crate::datetime::days_from_civil(d.year, d.month as u32, d.day as i64)
}

pub fn from_epoch_days(days: i64) -> IsoDate {
    let (y, m, d) = crate::datetime::civil_from_days(days);
    IsoDate { year: y, month: m as u8, day: d as u8 }
}

/// ISODateToEpochDays(year, month0, day) with an unbalanced month.
pub fn epoch_days_unbalanced(year: i64, month1: i64, day: i64) -> i64 {
    let m0 = month1 - 1;
    let y = year + m0.div_euclid(12);
    let m = m0.rem_euclid(12) + 1;
    crate::datetime::days_from_civil(y, m as u32, 1) + day - 1
}

/// BalanceISODate(year, month, day)
pub fn balance_date(year: i64, month1: i64, day: i64) -> IsoDate {
    from_epoch_days(epoch_days_unbalanced(year, month1, day))
}

/// BalanceISOYearMonth(year, month)
pub fn balance_year_month(year: i64, month1: i64) -> (i64, u8) {
    let m0 = month1 - 1;
    (year + m0.div_euclid(12), (m0.rem_euclid(12) + 1) as u8)
}

pub fn add_days(d: IsoDate, days: i64) -> IsoDate {
    from_epoch_days(epoch_days(d) + days)
}

pub fn compare_date(a: &IsoDate, b: &IsoDate) -> Ordering {
    (a.year, a.month, a.day).cmp(&(b.year, b.month, b.day))
}

pub fn compare_datetime(a: &IsoDateTime, b: &IsoDateTime) -> Ordering {
    compare_date(&a.date, &b.date).then(a.time.cmp(&b.time))
}

pub fn is_valid_iso_date(year: i64, month: i64, day: i64) -> bool {
    (1..=12).contains(&month) && day >= 1 && day <= days_in_month(year, month as u8) as i64
}

/// GetUTCEpochNanoseconds
pub fn utc_epoch_ns(d: &IsoDate, t: &Time) -> i128 {
    epoch_days(*d) as i128 * NS_PER_DAY + t.to_ns()
}

pub fn utc_epoch_ns_dt(dt: &IsoDateTime) -> i128 {
    utc_epoch_ns(&dt.date, &dt.time)
}

pub fn epoch_ns_valid(ns: i128) -> bool {
    (NS_MIN_INSTANT..=NS_MAX_INSTANT).contains(&ns)
}

/// ISODateTimeWithinLimits
pub fn datetime_within_limits(d: &IsoDate, t: &Time) -> bool {
    if d.year.abs() > 300_000 {
        return false;
    }
    let days = epoch_days(*d);
    if days.abs() > 100_000_001 {
        return false;
    }
    let ns = utc_epoch_ns(d, t);
    ns > NS_MIN_INSTANT - NS_PER_DAY && ns < NS_MAX_INSTANT + NS_PER_DAY
}

/// ISODateWithinLimits
pub fn date_within_limits(d: &IsoDate) -> bool {
    datetime_within_limits(d, &Time::NOON)
}

/// ISOYearMonthWithinLimits
pub fn year_month_within_limits(d: &IsoDate) -> bool {
    if d.year < -271821 || d.year > 275760 {
        return false;
    }
    if d.year == -271821 && d.month < 4 {
        return false;
    }
    if d.year == 275760 && d.month > 9 {
        return false;
    }
    true
}

/// CheckISODaysRange: |epoch days| <= 10^8
pub fn days_in_range(d: &IsoDate) -> bool {
    d.year.abs() <= 300_000 && epoch_days(*d).abs() <= 100_000_000
}

/// Date-time of an epoch-nanoseconds value plus an offset.
pub fn datetime_from_epoch_ns(ns: i128) -> IsoDateTime {
    let days = ns.div_euclid(NS_PER_DAY);
    let rem = ns.rem_euclid(NS_PER_DAY);
    let (_, time) = Time::balance(rem);
    IsoDateTime { date: from_epoch_days(days as i64), time }
}

/// BalanceISODateTime(date, time + extra nanoseconds)
pub fn balance_datetime(d: &IsoDate, t: &Time, extra_ns: i128) -> IsoDateTime {
    let (days, time) = Time::balance(t.to_ns() + extra_ns);
    IsoDateTime { date: add_days(*d, days), time }
}

/// 1 = Monday ... 7 = Sunday
pub fn day_of_week(d: &IsoDate) -> u8 {
    // 1970-01-01 was a Thursday (4)
    ((epoch_days(*d) + 3).rem_euclid(7) + 1) as u8
}

pub fn day_of_year(d: &IsoDate) -> u16 {
    (epoch_days(*d) - crate::datetime::days_from_civil(d.year, 1, 1) + 1) as u16
}

/// ISO week number and week-year.
pub fn week_of_year(d: &IsoDate) -> (u8, i64) {
    let doy = day_of_year(d) as i64;
    let dow = day_of_week(d) as i64;
    let doj = day_of_week(&IsoDate::new(d.year, 1, 1)) as i64;
    let week = (doy - dow + 10).div_euclid(7);
    if week < 1 {
        if doj == 5 || (doj == 6 && is_leap(d.year - 1)) {
            return (53, d.year - 1);
        }
        return (52, d.year - 1);
    }
    if week == 53 && (days_in_year(d.year) as i64 - doy) < 4 - dow {
        return (1, d.year + 1);
    }
    (week as u8, d.year)
}

/// RegulateISODate with "constrain"
pub fn constrain_date(year: i64, month: i64, day: i64) -> IsoDate {
    let m = month.clamp(1, 12) as u8;
    let dim = days_in_month(year, m) as i64;
    IsoDate { year, month: m, day: day.clamp(1, dim) as u8 }
}

/// Exact quotient num/den (den > 0) rounded to the nearest f64 (ties to even).
pub fn div_to_f64(num: i128, den: i128) -> f64 {
    if den == 0 {
        return f64::NAN;
    }
    let neg = (num < 0) != (den < 0);
    let n = num.unsigned_abs();
    let d = den.unsigned_abs();
    let r = udiv_to_f64(n, d);
    if neg {
        -r
    } else {
        r
    }
}

fn bitlen(x: u128) -> u32 {
    128 - x.leading_zeros()
}

fn udiv_to_f64(n: u128, d: u128) -> f64 {
    if n == 0 {
        return 0.0;
    }
    let mut m = n / d;
    let mut rem = n % d;
    let mut e: i32 = 0;
    // collect at least 55 significant bits
    while bitlen(m) < 55 {
        // rem < d <= 2^127 so 2*rem fits
        let r2 = rem << 1;
        m <<= 1;
        if r2 >= d {
            m |= 1;
            rem = r2 - d;
        } else {
            rem = r2;
        }
        e -= 1;
        if e < -1200 {
            break;
        }
    }
    let sticky = rem != 0;
    let bl = bitlen(m);
    if bl > 53 {
        let extra = bl - 53;
        let low = m & ((1u128 << extra) - 1);
        let half = 1u128 << (extra - 1);
        m >>= extra;
        e += extra as i32;
        if low > half || (low == half && (sticky || (m & 1) == 1)) {
            m += 1;
        }
    }
    (m as f64) * 2f64.powi(e)
}

/// f64 holding an integer -> i128 (caller guarantees |x| < 2^120).
pub fn f2i(x: f64) -> i128 {
    x as i128
}

//! ISO 8601 / RFC 9557 string parsing for Temporal (no VM access).
//!
//! The grammar follows the Temporal specification.  Each `parse_*` entry
//! point must consume the whole string; callers decide which forms they
//! accept and produce their own error messages.

use super::iso::{days_in_month, is_valid_iso_date, Time};

#[derive(Clone, Debug, Default)]
pub struct Offset {
    /// signed offset in nanoseconds
    pub ns: i128,
    /// written with seconds (sub-minute precision)
    pub has_seconds: bool,
    pub text: String,
}

#[derive(Clone, Debug)]
pub struct TzAnnotation {
    pub critical: bool,
    pub text: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Copy)]
pub enum Form {
    /// Date [T Time [offset]]
    DateTime,
    /// YYYY-MM
    YearMonth,
    /// [--]MM-DD
    MonthDay,
    /// [T] Time [offset]
    Time,
}

#[derive(Clone, Debug)]
pub struct Parsed {
    pub form: Form,
    pub year: Option<i64>,
    pub month: u8,
    pub day: Option<u8>,
    pub time: Option<Time>,
    /// a time designator (T/t) preceded the time (Time form only)
    pub has_designator: bool,
    pub z: bool,
    pub offset: Option<Offset>,
    pub tz: Option<TzAnnotation>,
    pub calendar: Option<String>,
    /// byte length of the "Time UTCOffset" part (Time form, for ambiguity checks)
    pub time_part_end: usize,
}

impl Parsed {
    fn new(form: Form) -> Parsed {
        Parsed {
            form,
            year: None,
            month: 1,
            day: None,
            time: None,
            has_designator: false,
            z: false,
            offset: None,
            tz: None,
            calendar: None,
            time_part_end: 0,
        }
    }
}

struct Cur<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> Cur<'a> {
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn peek_at(&self, k: usize) -> Option<u8> {
        self.b.get(self.i + k).copied()
    }
    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.i += 1;
            true
        } else {
            false
        }
    }
    fn done(&self) -> bool {
        self.i >= self.b.len()
    }
    fn digits(&mut self, n: usize) -> Option<i64> {
        let mut v: i64 = 0;
        for k in 0..n {
            let c = self.peek_at(k)?;
            if !c.is_ascii_digit() {
                return None;
            }
            v = v * 10 + (c - b'0') as i64;
        }
        self.i += n;
        Some(v)
    }
    fn is_digit_at(&self, k: usize) -> bool {
        self.peek_at(k).map_or(false, |c| c.is_ascii_digit())
    }
}

fn parse_year(c: &mut Cur) -> Option<i64> {
    match c.peek()? {
        b'+' | b'-' => {
            let neg = c.peek() == Some(b'-');
            let save = c.i;
            c.i += 1;
            match c.digits(6) {
                Some(v) => {
                    if neg && v == 0 {
                        c.i = save;
                        return None;
                    }
                    Some(if neg { -v } else { v })
                }
                None => {
                    c.i = save;
                    None
                }
            }
        }
        _ => c.digits(4),
    }
}

fn parse_month(c: &mut Cur) -> Option<u8> {
    let save = c.i;
    let v = c.digits(2)?;
    if (1..=12).contains(&v) {
        Some(v as u8)
    } else {
        c.i = save;
        None
    }
}

fn parse_day(c: &mut Cur) -> Option<u8> {
    let save = c.i;
    let v = c.digits(2)?;
    if (1..=31).contains(&v) {
        Some(v as u8)
    } else {
        c.i = save;
        None
    }
}

/// Date: YYYY-MM-DD | YYYYMMDD (validated)
fn parse_date(c: &mut Cur) -> Option<(i64, u8, u8)> {
    let save = c.i;
    let r = (|| {
        let y = parse_year(c)?;
        let ext = c.eat(b'-');
        let m = parse_month(c)?;
        if ext {
            if !c.eat(b'-') {
                return None;
            }
        } else if c.peek() == Some(b'-') {
            return None;
        }
        let d = parse_day(c)?;
        Some((y, m, d))
    })();
    match r {
        Some((y, m, d)) if is_valid_iso_date(y, m as i64, d as i64) => Some((y, m, d)),
        _ => {
            c.i = save;
            None
        }
    }
}

fn parse_fraction(c: &mut Cur) -> Option<Option<u32>> {
    // returns Some(None) if there is no fraction, Some(Some(ns)) if valid,
    // None on a malformed fraction
    match c.peek() {
        Some(b'.') | Some(b',') => {
            let st = c.i + 1;
            let mut k = st;
            while k < c.b.len() && c.b[k].is_ascii_digit() {
                k += 1;
            }
            let n = k - st;
            if n == 0 || n > 9 {
                return None;
            }
            let mut v: u32 = 0;
            for j in 0..9 {
                let d = if j < n { (c.b[st + j] - b'0') as u32 } else { 0 };
                v = v * 10 + d;
            }
            c.i = k;
            Some(Some(v))
        }
        _ => Some(None),
    }
}

fn two_digit_hour(c: &mut Cur) -> Option<u8> {
    let save = c.i;
    let v = c.digits(2)?;
    if v <= 23 {
        Some(v as u8)
    } else {
        c.i = save;
        None
    }
}

fn minute_second(c: &mut Cur) -> Option<u8> {
    let save = c.i;
    let v = c.digits(2)?;
    if v <= 59 {
        Some(v as u8)
    } else {
        c.i = save;
        None
    }
}

/// Time: HH[[:]MM[[:]SS[.fff]]] with consistent separators
fn parse_time(c: &mut Cur) -> Option<Time> {
    let save = c.i;
    let r = (|| {
        let h = two_digit_hour(c)?;
        let mut t = Time { hour: h, ..Time::default() };
        let ext = if c.peek() == Some(b':') {
            true
        } else if c.is_digit_at(0) {
            false
        } else {
            return Some(t);
        };
        if ext {
            c.i += 1;
        }
        t.minute = minute_second(c)?;
        let has_sec = if ext {
            if c.peek() == Some(b':') {
                c.i += 1;
                true
            } else {
                false
            }
        } else {
            c.is_digit_at(0)
        };
        if !has_sec {
            if ext && c.is_digit_at(0) {
                return None;
            }
            return Some(t);
        }
        let s = c.digits(2)?;
        if s > 60 {
            return None;
        }
        t.second = if s == 60 { 59 } else { s as u8 };
        if let Some(f) = parse_fraction(c)? {
            t.millisecond = (f / 1_000_000) as u16;
            t.microsecond = (f / 1000 % 1000) as u16;
            t.nanosecond = (f % 1000) as u16;
        }
        Some(t)
    })();
    if r.is_none() {
        c.i = save;
    }
    r
}

/// UTCOffset with optional sub-minute precision: ±HH[[:]MM[[:]SS[.f]]]
fn parse_offset(c: &mut Cur, allow_sub_minute: bool) -> Option<Offset> {
    let save = c.i;
    let r = (|| {
        let sign: i128 = match c.peek()? {
            b'+' => 1,
            b'-' => -1,
            _ => return None,
        };
        c.i += 1;
        let h = two_digit_hour(c)?;
        let mut ns = h as i128 * 3_600_000_000_000;
        let mut has_seconds = false;
        let ext = if c.peek() == Some(b':') {
            true
        } else if c.is_digit_at(0) {
            false
        } else {
            return Some((sign, ns, has_seconds));
        };
        if ext {
            c.i += 1;
        }
        let m = minute_second(c)?;
        ns += m as i128 * 60_000_000_000;
        let more = if ext { c.peek() == Some(b':') } else { c.is_digit_at(0) };
        if !more {
            if !ext && c.is_digit_at(0) {
                return None;
            }
            return Some((sign, ns, has_seconds));
        }
        if !allow_sub_minute {
            return None;
        }
        if ext {
            c.i += 1;
        }
        let s = minute_second(c)?;
        ns += s as i128 * 1_000_000_000;
        has_seconds = true;
        if let Some(f) = parse_fraction(c)? {
            ns += f as i128;
        }
        Some((sign, ns, has_seconds))
    })();
    match r {
        Some((sign, ns, has_seconds)) => {
            let text = String::from_utf8_lossy(&c.b[save..c.i]).to_string();
            Some(Offset { ns: sign * ns, has_seconds, text })
        }
        None => {
            c.i = save;
            None
        }
    }
}

fn is_tz_leading(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'.' || c == b'_'
}

fn is_tz_char(c: u8) -> bool {
    is_tz_leading(c) || c.is_ascii_digit() || c == b'-' || c == b'+'
}

/// TimeZoneIANAName
pub fn is_iana_name_syntax(s: &[u8]) -> bool {
    if s.is_empty() {
        return false;
    }
    for comp in s.split(|&c| c == b'/') {
        if comp.is_empty() || !is_tz_leading(comp[0]) || !comp.iter().all(|&c| is_tz_char(c)) {
            return false;
        }
    }
    true
}

fn is_akey_leading(c: u8) -> bool {
    c.is_ascii_lowercase() || c == b'_'
}

fn is_akey_char(c: u8) -> bool {
    is_akey_leading(c) || c.is_ascii_digit() || c == b'-'
}

/// AnnotationValue: alnum+ ("-" alnum+)*
pub fn is_annotation_value(s: &[u8]) -> bool {
    !s.is_empty() && s.split(|&c| c == b'-').all(|p| !p.is_empty() && p.iter().all(|c| c.is_ascii_alphanumeric()))
}

/// Parse the trailing [time zone] and [key=value] annotations.
fn parse_annotations(c: &mut Cur, p: &mut Parsed) -> Option<()> {
    let mut first = true;
    let mut calendar_critical = false;
    while c.peek() == Some(b'[') {
        let start = c.i + 1;
        let end = start + c.b[start..].iter().position(|&x| x == b']')?;
        let mut content = &c.b[start..end];
        let critical = content.first() == Some(&b'!');
        if critical {
            content = &content[1..];
        }
        if let Some(eq) = content.iter().position(|&x| x == b'=') {
            let key = &content[..eq];
            let value = &content[eq + 1..];
            if key.is_empty() || !is_akey_leading(key[0]) || !key.iter().all(|&x| is_akey_char(x)) {
                return None;
            }
            if !is_annotation_value(value) {
                return None;
            }
            if key == b"u-ca" {
                if p.calendar.is_none() {
                    p.calendar = Some(String::from_utf8_lossy(value).to_string());
                    calendar_critical = critical;
                } else if critical || calendar_critical {
                    return None;
                }
            } else if critical {
                return None;
            }
        } else {
            // time zone annotation: only one, before any other annotation
            if !first {
                return None;
            }
            let ok = if matches!(content.first(), Some(b'+') | Some(b'-')) {
                let mut cc = Cur { b: content, i: 0 };
                parse_offset(&mut cc, true).is_some() && cc.done()
            } else {
                is_iana_name_syntax(content)
            };
            if !ok {
                return None;
            }
            p.tz = Some(TzAnnotation { critical, text: String::from_utf8_lossy(content).to_string() });
        }
        first = false;
        c.i = end + 1;
    }
    Some(())
}

fn parse_utc_offset_or_z(c: &mut Cur, p: &mut Parsed) -> Option<()> {
    match c.peek() {
        Some(b'Z') | Some(b'z') => {
            c.i += 1;
            p.z = true;
        }
        Some(b'+') | Some(b'-') => {
            p.offset = Some(parse_offset(c, true)?);
        }
        _ => {}
    }
    Some(())
}

/// Date [ (T|t|space) Time [Z|offset] ] [annotations]
pub fn parse_date_time(s: &str) -> Option<Parsed> {
    let mut c = Cur { b: s.as_bytes(), i: 0 };
    let mut p = Parsed::new(Form::DateTime);
    let (y, m, d) = parse_date(&mut c)?;
    p.year = Some(y);
    p.month = m;
    p.day = Some(d);
    if matches!(c.peek(), Some(b'T') | Some(b't') | Some(b' ')) {
        c.i += 1;
        p.time = Some(parse_time(&mut c)?);
        parse_utc_offset_or_z(&mut c, &mut p)?;
    }
    parse_annotations(&mut c, &mut p)?;
    if !c.done() {
        return None;
    }
    Some(p)
}

/// DateSpecYearMonth [annotations]
pub fn parse_year_month(s: &str) -> Option<Parsed> {
    let mut c = Cur { b: s.as_bytes(), i: 0 };
    let mut p = Parsed::new(Form::YearMonth);
    let y = parse_year(&mut c)?;
    c.eat(b'-');
    let m = parse_month(&mut c)?;
    p.year = Some(y);
    p.month = m;
    parse_annotations(&mut c, &mut p)?;
    if !c.done() {
        return None;
    }
    Some(p)
}

fn month_day_prefix(c: &mut Cur) -> Option<(u8, u8)> {
    if c.peek() == Some(b'-') && c.peek_at(1) == Some(b'-') {
        c.i += 2;
    }
    let m = parse_month(c)?;
    c.eat(b'-');
    let d = parse_day(c)?;
    let max = if m == 2 { 29 } else { days_in_month(1972, m) };
    if d > max {
        return None;
    }
    Some((m, d))
}

/// DateSpecMonthDay [annotations]
pub fn parse_month_day(s: &str) -> Option<Parsed> {
    let mut c = Cur { b: s.as_bytes(), i: 0 };
    let mut p = Parsed::new(Form::MonthDay);
    let (m, d) = month_day_prefix(&mut c)?;
    p.month = m;
    p.day = Some(d);
    parse_annotations(&mut c, &mut p)?;
    if !c.done() {
        return None;
    }
    Some(p)
}

/// [T] Time [Z|offset] [annotations]
pub fn parse_time_only(s: &str) -> Option<Parsed> {
    let mut c = Cur { b: s.as_bytes(), i: 0 };
    let mut p = Parsed::new(Form::Time);
    if matches!(c.peek(), Some(b'T') | Some(b't')) {
        c.i += 1;
        p.has_designator = true;
    }
    p.time = Some(parse_time(&mut c)?);
    parse_utc_offset_or_z(&mut c, &mut p)?;
    p.time_part_end = c.i;
    parse_annotations(&mut c, &mut p)?;
    if !c.done() {
        return None;
    }
    Some(p)
}

/// Is the "Time UTCOffset" part of an undesignated time string also a valid
/// DateSpecMonthDay or DateSpecYearMonth?
pub fn time_is_ambiguous(s: &str, p: &Parsed) -> bool {
    if p.has_designator {
        return false;
    }
    let part = &s[..p.time_part_end];
    let b = part.as_bytes();
    // DateSpecYearMonth
    {
        let mut c = Cur { b, i: 0 };
        if parse_year(&mut c).is_some() {
            c.eat(b'-');
            if parse_month(&mut c).is_some() && c.done() {
                return true;
            }
        }
    }
    {
        let mut c = Cur { b, i: 0 };
        if month_day_prefix(&mut c).is_some() && c.done() {
            return true;
        }
    }
    false
}

/// Exactly a UTC offset string (DateTimeUTCOffset, sub-minute allowed)
pub fn parse_offset_string(s: &str, allow_sub_minute: bool) -> Option<Offset> {
    let mut c = Cur { b: s.as_bytes(), i: 0 };
    let o = parse_offset(&mut c, allow_sub_minute)?;
    if !c.done() {
        return None;
    }
    Some(o)
}

/// Any of the ISO forms (used by calendar / time zone string parsing):
/// tries date-time, year-month, month-day and time.
pub fn parse_any(s: &str) -> Option<Parsed> {
    if let Some(p) = parse_date_time(s) {
        return Some(p);
    }
    if let Some(p) = parse_time_only(s) {
        if !time_is_ambiguous(s, &p) {
            return Some(p);
        }
    }
    if let Some(p) = parse_year_month(s) {
        return Some(p);
    }
    if let Some(p) = parse_month_day(s) {
        return Some(p);
    }
    None
}

/// Parsed duration string fields (unsigned magnitudes + sign).
#[derive(Clone, Debug, Default)]
pub struct DurationParts {
    pub negative: bool,
    pub years: f64,
    pub months: f64,
    pub weeks: f64,
    pub days: f64,
    pub hours: f64,
    pub minutes: f64,
    pub seconds: f64,
    pub milliseconds: f64,
    pub microseconds: f64,
    pub nanoseconds: f64,
}

fn digits_value(d: &[u8]) -> f64 {
    // decimal digit string -> nearest f64 (exact for <= 2^53)
    let s = std::str::from_utf8(d).unwrap_or("0");
    s.parse::<f64>().unwrap_or(0.0)
}

/// ISO 8601 duration: [+-]P[nY][nM][nW][nD][T[nH][nM][nS]] with an optional
/// fraction on the last time component.
pub fn parse_duration(s: &str) -> Option<DurationParts> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut r = DurationParts::default();
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        r.negative = b[i] == b'-';
        i += 1;
    }
    if i >= b.len() || !(b[i] == b'P' || b[i] == b'p') {
        return None;
    }
    i += 1;
    let mut any = false;
    // date part
    let date_designators = [b'Y', b'M', b'W', b'D'];
    let mut next_date = 0;
    let mut in_time = false;
    let mut next_time = 0;
    let time_designators = [b'H', b'M', b'S'];
    let mut time_any = false;
    let mut had_fraction = false;
    // fraction handling: total nanoseconds contributed by a fraction
    while i < b.len() {
        let c = b[i];
        if c == b'T' || c == b't' {
            if in_time {
                return None;
            }
            in_time = true;
            i += 1;
            continue;
        }
        if had_fraction {
            return None;
        }
        let st = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if i == st {
            return None;
        }
        let int_digits = &b[st..i];
        let mut frac: Option<(u64, u32)> = None;
        if i < b.len() && (b[i] == b'.' || b[i] == b',') {
            let fs = i + 1;
            let mut k = fs;
            while k < b.len() && b[k].is_ascii_digit() {
                k += 1;
            }
            let n = k - fs;
            if n == 0 || n > 9 {
                return None;
            }
            let mut v: u64 = 0;
            for j in 0..n {
                v = v * 10 + (b[fs + j] - b'0') as u64;
            }
            frac = Some((v, n as u32));
            i = k;
        }
        if i >= b.len() {
            return None;
        }
        let d = b[i].to_ascii_uppercase();
        i += 1;
        let v = digits_value(int_digits);
        if !in_time {
            if frac.is_some() {
                return None;
            }
            let pos = date_designators.iter().position(|&x| x == d)?;
            if pos < next_date {
                return None;
            }
            next_date = pos + 1;
            match pos {
                0 => r.years = v,
                1 => r.months = v,
                2 => r.weeks = v,
                _ => r.days = v,
            }
            any = true;
        } else {
            let pos = time_designators.iter().position(|&x| x == d)?;
            if pos < next_time {
                return None;
            }
            next_time = pos + 1;
            time_any = true;
            any = true;
            // fraction contribution in nanoseconds
            let unit_ns: u128 = match pos {
                0 => 3_600_000_000_000,
                1 => 60_000_000_000,
                _ => 1_000_000_000,
            };
            let frac_ns: u128 = match frac {
                Some((fv, n)) => {
                    had_fraction = true;
                    (fv as u128) * unit_ns / 10u128.pow(n)
                }
                None => 0,
            };
            match pos {
                0 => {
                    r.hours = v;
                    let mins = frac_ns / 60_000_000_000;
                    let rem = frac_ns % 60_000_000_000;
                    r.minutes = mins as f64;
                    r.seconds = (rem / 1_000_000_000) as f64;
                    let rem = rem % 1_000_000_000;
                    r.milliseconds = (rem / 1_000_000) as f64;
                    r.microseconds = (rem / 1000 % 1000) as f64;
                    r.nanoseconds = (rem % 1000) as f64;
                }
                1 => {
                    r.minutes = v;
                    r.seconds = (frac_ns / 1_000_000_000) as f64;
                    let rem = frac_ns % 1_000_000_000;
                    r.milliseconds = (rem / 1_000_000) as f64;
                    r.microseconds = (rem / 1000 % 1000) as f64;
                    r.nanoseconds = (rem % 1000) as f64;
                }
                _ => {
                    r.seconds = v;
                    r.milliseconds = (frac_ns / 1_000_000) as f64;
                    r.microseconds = (frac_ns / 1000 % 1000) as f64;
                    r.nanoseconds = (frac_ns % 1000) as f64;
                }
            }
        }
    }
    if !any || (in_time && !time_any) {
        return None;
    }
    Some(r)
}

