//! Time zones for Temporal: fixed UTC offsets (minute precision) and named
//! zones resolved through `crate::datetime` (system tz database).

use std::rc::Rc;

use super::iso::*;
use super::parse;
use super::*;
use crate::datetime as dt;

pub struct NamedTz {
    pub id: String,
    pub zone: dt::TimeZone,
    pub primary: String,
}

#[derive(Clone)]
pub enum Tz {
    /// offset in minutes
    Offset(i64),
    Named(Rc<NamedTz>),
}

impl std::fmt::Debug for Tz {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Tz({})", self.id())
    }
}

pub const MSG_GAP: &str = "no such local time (skipped by a DST gap)";
pub const MSG_OVERLAP: &str = "ambiguous local time (DST overlap)";

impl Tz {
    pub fn id(&self) -> String {
        match self {
            Tz::Offset(m) => fmt_offset_minutes(*m),
            Tz::Named(n) => n.id.clone(),
        }
    }

    pub fn is_offset(&self) -> bool {
        matches!(self, Tz::Offset(_))
    }

    pub fn utc() -> Tz {
        Tz::named(dt::TimeZone::Utc)
    }

    fn named(zone: dt::TimeZone) -> Tz {
        let id = zone.id();
        let primary = zone.primary_id();
        Tz::Named(Rc::new(NamedTz { id, zone, primary }))
    }

    /// ParseTimeZoneIdentifier + GetAvailableNamedTimeZoneIdentifier.
    /// Err(true) = not identifier syntax, Err(false) = unknown zone.
    pub fn from_identifier_ex(s: &str) -> Result<Tz, bool> {
        if s.starts_with('+') || s.starts_with('-') {
            return match parse::parse_offset_string(s, false) {
                Some(o) => Ok(Tz::Offset((o.ns / NS_PER_MINUTE) as i64)),
                None => Err(true),
            };
        }
        if !parse::is_iana_name_syntax(s.as_bytes()) {
            return Err(true);
        }
        match dt::TimeZone::from_name(s) {
            Some(z @ dt::TimeZone::Utc) | Some(z @ dt::TimeZone::Named(_)) => Ok(Tz::named(z)),
            Some(dt::TimeZone::Fixed(m)) => Ok(Tz::Offset(m as i64)),
            None => Err(false),
        }
    }

    pub fn from_identifier(s: &str) -> Option<Tz> {
        Tz::from_identifier_ex(s).ok()
    }

    /// ParseTemporalTimeZoneString + identifier resolution
    pub fn from_time_zone_string(s: &str) -> Option<Tz> {
        match Tz::from_identifier_ex(s) {
            Ok(tz) => return Some(tz),
            Err(false) => return None,
            Err(true) => {}
        }
        let p = parse::parse_any(s)?;
        if let Some(a) = &p.tz {
            return Tz::from_identifier(&a.text);
        }
        if p.z {
            return Some(Tz::utc());
        }
        if let Some(o) = &p.offset {
            if o.has_seconds {
                return None;
            }
            return Some(Tz::Offset((o.ns / NS_PER_MINUTE) as i64));
        }
        None
    }

    /// GetOffsetNanosecondsFor
    pub fn offset_ns(&self, ns: i128) -> i128 {
        match self {
            Tz::Offset(m) => *m as i128 * NS_PER_MINUTE,
            Tz::Named(n) => {
                let ms = ns.div_euclid(1_000_000) as f64;
                n.zone.offset_ms(ms) as i128 * 1_000_000
            }
        }
    }

    /// GetISODateTimeFor
    pub fn datetime_for(&self, ns: i128) -> IsoDateTime {
        datetime_from_epoch_ns(ns + self.offset_ns(ns))
    }

    /// GetPossibleEpochNanoseconds
    pub fn possible_epoch_ns(&self, d: &IsoDateTime) -> TRes<Vec<i128>> {
        let v = match self {
            Tz::Offset(m) => {
                let b = balance_datetime(&d.date, &d.time, -(*m as i128) * NS_PER_MINUTE);
                if !days_in_range(&b.date) {
                    return rerr(MSG_INSTANT_RANGE);
                }
                vec![utc_epoch_ns_dt(&b)]
            }
            Tz::Named(_) => {
                if !days_in_range(&d.date) {
                    return rerr(MSG_INSTANT_RANGE);
                }
                let local = utc_epoch_ns_dt(d);
                let before = self.offset_ns(local - NS_PER_DAY);
                let after = self.offset_ns(local + NS_PER_DAY);
                let mut cands = vec![before];
                if after != before {
                    cands.push(after);
                }
                let mut out = Vec::new();
                for o in cands {
                    let e = local - o;
                    if self.datetime_for(e) == *d {
                        out.push(e);
                    }
                }
                out.sort();
                out.dedup();
                out
            }
        };
        for &x in &v {
            if !epoch_ns_valid(x) {
                return rerr(MSG_INSTANT_RANGE);
            }
        }
        Ok(v)
    }

    /// DisambiguatePossibleEpochNanoseconds
    pub fn disambiguate(&self, possible: Vec<i128>, d: &IsoDateTime, dis: Disambiguation) -> TRes<i128> {
        let n = possible.len();
        if n == 1 {
            return Ok(possible[0]);
        }
        if n != 0 {
            return match dis {
                Disambiguation::Earlier | Disambiguation::Compatible => Ok(possible[0]),
                Disambiguation::Later => Ok(possible[n - 1]),
                Disambiguation::Reject => rerr(MSG_OVERLAP),
            };
        }
        if dis == Disambiguation::Reject {
            return rerr(MSG_GAP);
        }
        let utc = utc_epoch_ns_dt(d);
        let day_before = utc - NS_PER_DAY;
        let day_after = utc + NS_PER_DAY;
        if !epoch_ns_valid(day_before) || !epoch_ns_valid(day_after) {
            return rerr(MSG_INSTANT_RANGE);
        }
        let nanos = self.offset_ns(day_after) - self.offset_ns(day_before);
        if dis == Disambiguation::Earlier {
            let e = balance_datetime(&d.date, &d.time, -nanos);
            let p = self.possible_epoch_ns(&e)?;
            return match p.first() {
                Some(&x) => Ok(x),
                None => rerr(MSG_GAP),
            };
        }
        let l = balance_datetime(&d.date, &d.time, nanos);
        let p = self.possible_epoch_ns(&l)?;
        match p.last() {
            Some(&x) => Ok(x),
            None => rerr(MSG_GAP),
        }
    }

    /// GetEpochNanosecondsFor
    pub fn epoch_ns_for(&self, d: &IsoDateTime, dis: Disambiguation) -> TRes<i128> {
        let p = self.possible_epoch_ns(d)?;
        self.disambiguate(p, d, dis)
    }

    /// GetStartOfDay
    pub fn start_of_day(&self, date: &IsoDate) -> TRes<i128> {
        let d = IsoDateTime { date: *date, time: Time::MIDNIGHT };
        let p = self.possible_epoch_ns(&d)?;
        if let Some(&x) = p.first() {
            return Ok(x);
        }
        let utc = utc_epoch_ns_dt(&d);
        match self.next_transition(utc - NS_PER_DAY) {
            Some(t) => Ok(t),
            None => rerr(MSG_INSTANT_RANGE),
        }
    }

    /// GetNamedTimeZoneNextTransition (strictly after `ns`)
    pub fn next_transition(&self, ns: i128) -> Option<i128> {
        match self {
            Tz::Offset(_) => None,
            Tz::Named(n) => {
                let secs = ns.div_euclid(NS_PER_SECOND);
                let secs = secs.clamp(i64::MIN as i128, i64::MAX as i128) as i64;
                let t = n.zone.next_offset_transition(secs)? as i128 * NS_PER_SECOND;
                if t > NS_MAX_INSTANT {
                    None
                } else {
                    Some(t)
                }
            }
        }
    }

    /// GetNamedTimeZonePreviousTransition (strictly before `ns`)
    pub fn prev_transition(&self, ns: i128) -> Option<i128> {
        match self {
            Tz::Offset(_) => None,
            Tz::Named(n) => {
                let secs = -((-ns).div_euclid(NS_PER_SECOND)); // ceil
                let secs = secs.clamp(i64::MIN as i128, i64::MAX as i128) as i64;
                let t = n.zone.prev_offset_transition(secs)? as i128 * NS_PER_SECOND;
                if t < NS_MIN_INSTANT {
                    None
                } else {
                    Some(t)
                }
            }
        }
    }

    /// TimeZoneEquals
    pub fn equals(&self, other: &Tz) -> bool {
        match (self, other) {
            (Tz::Offset(a), Tz::Offset(b)) => a == b,
            (Tz::Named(a), Tz::Named(b)) => a.id == b.id || a.primary == b.primary,
            _ => false,
        }
    }
}

//! Duration records and the difference / rounding algorithms
//! (DifferenceISODateTime, RoundRelativeDuration, Nudge*, Bubble*, ...).

use super::calendar::{self, Cal};
use super::iso::*;
use super::parse;
use super::tz::Tz;
use super::*;

pub const MSG_DUR_RANGE: &str = "duration is outside the valid range";
pub const MSG_DUR_FIELD_RANGE: &str = "duration field is outside the valid range";
pub const MSG_MIXED_SIGN: &str = "mixed-sign duration";

const TWO_32: f64 = 4294967296.0;

/// Temporal.Duration fields (float64 integers)
#[derive(Clone, Copy, Default, PartialEq, Debug)]
pub struct Dur {
    pub years: f64,
    pub months: f64,
    pub weeks: f64,
    pub days: f64,
    pub hours: f64,
    pub minutes: f64,
    pub seconds: f64,
    pub milliseconds: f64,
    pub microseconds: f64,
    pub nanoseconds: f64,
}

impl Dur {
    pub fn fields(&self) -> [f64; 10] {
        [
            self.years,
            self.months,
            self.weeks,
            self.days,
            self.hours,
            self.minutes,
            self.seconds,
            self.milliseconds,
            self.microseconds,
            self.nanoseconds,
        ]
    }

    pub fn from_fields(f: [f64; 10]) -> Dur {
        let z = |x: f64| x + 0.0;
        Dur {
            years: z(f[0]),
            months: z(f[1]),
            weeks: z(f[2]),
            days: z(f[3]),
            hours: z(f[4]),
            minutes: z(f[5]),
            seconds: z(f[6]),
            milliseconds: z(f[7]),
            microseconds: z(f[8]),
            nanoseconds: z(f[9]),
        }
    }

    /// DurationSign
    pub fn sign(&self) -> i32 {
        for v in self.fields() {
            if v < 0.0 {
                return -1;
            }
            if v > 0.0 {
                return 1;
            }
        }
        0
    }

    /// CreateNegatedTemporalDuration
    pub fn negated(&self) -> Dur {
        let mut f = self.fields();
        for v in f.iter_mut() {
            *v = -*v;
        }
        Dur::from_fields(f)
    }

    pub fn abs(&self) -> Dur {
        let mut f = self.fields();
        for v in f.iter_mut() {
            *v = v.abs();
        }
        Dur::from_fields(f)
    }

    /// IsValidDuration (with the original's messages)
    pub fn validate(&self) -> TRes<()> {
        let f = self.fields();
        let mut sign = 0;
        for v in f {
            if !v.is_finite() {
                return rerr("value must be finite");
            }
            if v > 0.0 {
                if sign < 0 {
                    return rerr(MSG_MIXED_SIGN);
                }
                sign = 1;
            } else if v < 0.0 {
                if sign > 0 {
                    return rerr(MSG_MIXED_SIGN);
                }
                sign = -1;
            }
        }
        if self.years.abs() >= TWO_32 || self.months.abs() >= TWO_32 || self.weeks.abs() >= TWO_32 {
            return rerr(MSG_DUR_FIELD_RANGE);
        }
        for v in &f[3..] {
            if v.abs() >= 1e30 {
                return rerr(MSG_DUR_RANGE);
            }
        }
        let total = self.days as i128 * NS_PER_DAY + time_from_components(self);
        if total.abs() >= 9_007_199_254_740_992 * NS_PER_SECOND {
            return rerr(MSG_DUR_RANGE);
        }
        Ok(())
    }

    /// DefaultTemporalLargestUnit
    pub fn default_largest_unit(&self) -> Unit {
        for (i, v) in self.fields().iter().enumerate() {
            if *v != 0.0 {
                return Unit::ALL[i];
            }
        }
        Unit::Nanosecond
    }

    /// ParseTemporalDurationString
    pub fn parse(s: &str) -> TRes<Dur> {
        let p = match parse::parse_duration(s) {
            Some(p) => p,
            None => return rerr("invalid duration"),
        };
        let k = if p.negative { -1.0 } else { 1.0 };
        let d = Dur::from_fields([
            p.years * k,
            p.months * k,
            p.weeks * k,
            p.days * k,
            p.hours * k,
            p.minutes * k,
            p.seconds * k,
            p.milliseconds * k,
            p.microseconds * k,
            p.nanoseconds * k,
        ]);
        d.validate()?;
        Ok(d)
    }

    /// TemporalDurationToString
    pub fn to_string_with(&self, precision: Precision) -> String {
        let sign = self.sign();
        let n = |v: f64| format!("{}", v.abs() as u128);
        let mut date = String::new();
        if self.years != 0.0 {
            date += &format!("{}Y", n(self.years));
        }
        if self.months != 0.0 {
            date += &format!("{}M", n(self.months));
        }
        if self.weeks != 0.0 {
            date += &format!("{}W", n(self.weeks));
        }
        if self.days != 0.0 {
            date += &format!("{}D", n(self.days));
        }
        let mut time = String::new();
        if self.hours != 0.0 {
            time += &format!("{}H", n(self.hours));
        }
        if self.minutes != 0.0 {
            time += &format!("{}M", n(self.minutes));
        }
        let zero_minutes_and_higher = self.fields()[..6].iter().all(|v| *v == 0.0);
        let secs = (self.seconds as i128 * NS_PER_SECOND
            + self.milliseconds as i128 * 1_000_000
            + self.microseconds as i128 * 1000
            + self.nanoseconds as i128)
            .abs();
        if secs != 0 || zero_minutes_and_higher || precision != Precision::Auto {
            let whole = secs / NS_PER_SECOND;
            let frac = (secs % NS_PER_SECOND) as u32;
            time += &format!("{}{}S", whole, fmt_fraction(frac, precision));
        }
        let mut r = String::new();
        if sign < 0 {
            r.push('-');
        }
        r.push('P');
        r += &date;
        if !time.is_empty() {
            r.push('T');
            r += &time;
        }
        r
    }
}

/// TimeDurationFromComponents(hours ... nanoseconds) of a valid duration
pub fn time_from_components(d: &Dur) -> i128 {
    d.hours as i128 * NS_PER_HOUR
        + d.minutes as i128 * NS_PER_MINUTE
        + d.seconds as i128 * NS_PER_SECOND
        + d.milliseconds as i128 * 1_000_000
        + d.microseconds as i128 * 1000
        + d.nanoseconds as i128
}

/// Date Duration Record
#[derive(Clone, Copy, Default, PartialEq, Eq, Debug)]
pub struct DateDur {
    pub years: i64,
    pub months: i64,
    pub weeks: i64,
    pub days: i64,
}

impl DateDur {
    pub fn new(years: i64, months: i64, weeks: i64, days: i64) -> DateDur {
        DateDur { years, months, weeks, days }
    }

    pub fn sign(&self) -> i64 {
        for v in [self.years, self.months, self.weeks, self.days] {
            if v != 0 {
                return v.signum();
            }
        }
        0
    }

    /// CreateDateDurationRecord validation
    pub fn validate(&self) -> TRes<DateDur> {
        let d = Dur {
            years: self.years as f64,
            months: self.months as f64,
            weeks: self.weeks as f64,
            days: self.days as f64,
            ..Dur::default()
        };
        d.validate()?;
        Ok(*self)
    }

    /// AdjustDateDurationRecord(days, weeks, months)
    pub fn adjust(&self, days: i64, weeks: Option<i64>, months: Option<i64>) -> TRes<DateDur> {
        DateDur {
            years: self.years,
            months: months.unwrap_or(self.months),
            weeks: weeks.unwrap_or(self.weeks),
            days,
        }
        .validate()
    }
}

/// Internal Duration Record
#[derive(Clone, Copy, Default, PartialEq, Eq, Debug)]
pub struct IDur {
    pub date: DateDur,
    pub time: i128,
}

impl IDur {
    pub fn sign(&self) -> i64 {
        let s = self.date.sign();
        if s != 0 {
            return s;
        }
        self.time.signum() as i64
    }
}

/// ToInternalDurationRecord
pub fn to_internal(d: &Dur) -> IDur {
    IDur {
        date: DateDur::new(d.years as i64, d.months as i64, d.weeks as i64, d.days as i64),
        time: time_from_components(d),
    }
}

/// ToInternalDurationRecordWith24HourDays
pub fn to_internal_24h(d: &Dur) -> TRes<IDur> {
    let t = add_24h_days(time_from_components(d), d.days as i64)?;
    Ok(IDur { date: DateDur::new(d.years as i64, d.months as i64, d.weeks as i64, 0), time: t })
}

/// ToDateDurationRecordWithoutTime
pub fn to_date_duration_without_time(d: &Dur) -> TRes<DateDur> {
    let i = to_internal_24h(d)?;
    let days = i.time / NS_PER_DAY;
    DateDur::new(i.date.years, i.date.months, i.date.weeks, days as i64).validate()
}

pub fn check_time(t: i128) -> TRes<i128> {
    if t.abs() > MAX_TIME_DURATION {
        return rerr(MSG_DUR_RANGE);
    }
    Ok(t)
}

/// Add24HourDaysToTimeDuration
pub fn add_24h_days(t: i128, days: i64) -> TRes<i128> {
    check_time(t + days as i128 * NS_PER_DAY)
}

/// AddTimeDuration
pub fn add_time(a: i128, b: i128) -> TRes<i128> {
    check_time(a + b)
}

/// TemporalDurationFromInternal
pub fn from_internal(i: &IDur, largest: Unit) -> TRes<Dur> {
    let sign = i.time.signum();
    let mut ns = i.time.abs();
    let (mut days, mut hours, mut minutes, mut seconds, mut ms, mut us) = (0i128, 0i128, 0i128, 0i128, 0i128, 0i128);
    match largest {
        Unit::Year | Unit::Month | Unit::Week | Unit::Day | Unit::Hour | Unit::Minute | Unit::Second | Unit::Millisecond | Unit::Microsecond => {
            us = ns / 1000;
            ns %= 1000;
            if largest != Unit::Microsecond {
                ms = us / 1000;
                us %= 1000;
                if largest != Unit::Millisecond {
                    seconds = ms / 1000;
                    ms %= 1000;
                    if largest != Unit::Second {
                        minutes = seconds / 60;
                        seconds %= 60;
                        if largest != Unit::Minute {
                            hours = minutes / 60;
                            minutes %= 60;
                            if largest != Unit::Hour {
                                days = hours / 24;
                                hours %= 24;
                            }
                        }
                    }
                }
            }
        }
        Unit::Nanosecond => {}
    }
    let f = |v: i128| (v * sign) as f64;
    let d = Dur::from_fields([
        i.date.years as f64,
        i.date.months as f64,
        i.date.weeks as f64,
        (i.date.days as i128 + days * sign) as f64,
        f(hours),
        f(minutes),
        f(seconds),
        f(ms),
        f(us),
        f(ns),
    ]);
    d.validate()?;
    Ok(d)
}

/// RoundTimeDurationToIncrement
pub fn round_time_to_increment(t: i128, increment: i128, mode: RoundingMode) -> TRes<i128> {
    check_time(round_to_increment(t, increment, mode))
}

/// RoundTimeDuration
pub fn round_time_duration(t: i128, increment: i128, unit: Unit, mode: RoundingMode) -> TRes<i128> {
    round_time_to_increment(t, unit.ns() * increment, mode)
}

/// TotalTimeDuration
pub fn total_time(t: i128, unit: Unit) -> f64 {
    div_to_f64(t, unit.ns())
}

