}

pub fn in_leap_year(_cal: Cal, y: i64) -> bool {
    is_leap(y)
}

pub fn month_code(_cal: Cal, _y: i64, m: u8) -> MonthCode {
    MonthCode { num: m, leap: false }
}

pub fn ordinal_of_code(_cal: Cal, _y: i64, mc: MonthCode) -> Option<u8> {
    if !mc.leap && (1..=12).contains(&mc.num) {
        Some(mc.num)
    } else {
        None
    }
}

pub fn code_valid(_cal: Cal, mc: MonthCode) -> bool {
    !mc.leap && (1..=12).contains(&mc.num)
}

pub fn constrain_code(_cal: Cal, _y: i64, mc: MonthCode) -> u8 {
    mc.num.clamp(1, 12)
}

pub fn era_of(_cal: Cal, _d: &IsoDate) -> Option<(String, i64)> {
