}

pub fn year_from_era(_cal: Cal, _era: &str, _ey: i64) -> Option<i64> {
    None
}

pub fn month_day_to_iso_reference(_cal: Cal, f: &Fields, overflow: Overflow) -> TRes<IsoDate> {
    let r = super::calendar::regulate_iso_date(f.year.unwrap_or(1972.0), f.month.unwrap_or(1.0), f.day.unwrap_or(1.0), overflow)?;
    Ok(IsoDate::new(1972, r.month, r.day))
}

pub fn date_add(_cal: Cal, d: &IsoDate, dd: &DateDur, overflow: Overflow) -> TRes<IsoDate> {
    super::calendar::date_add(Cal::Iso8601, d, dd, overflow)
}

pub fn date_until(_cal: Cal, one: &IsoDate, two: &IsoDate, largest: Unit) -> DateDur {
