// ZonedDateTime / PlainDateTime with non-ISO calendars
let seed = Number(typeof process !== 'undefined' && process.argv[2] || 1);
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
function ri(a, b) { return a + Math.floor(rnd() * (b - a + 1)); }
function pick(arr) { return arr[ri(0, arr.length - 1)]; }
function t(label, f) {
  try { const r = f(); console.log(label, 'OK', typeof r === 'object' && r !== null ? String(r) : JSON.stringify(r)); }
  catch (e) { console.log(label, e.constructor.name + ': ' + e.message); }
}
const cals = ['hebrew', 'islamic-civil', 'islamic-umalqura', 'persian', 'indian', 'coptic', 'ethiopic', 'japanese', 'gregory', 'roc'];
const zones = ['America/New_York', 'Europe/London', 'Asia/Tokyo', 'UTC', '+05:30'];
const units = ['year', 'month', 'week', 'day', 'hour', 'minute'];
const modes = ['ceil', 'floor', 'halfExpand', 'trunc'];
for (let i = 0; i < 200; i++) {
  const cal = pick(cals);
  const ns = BigInt(ri(-500000000, 3000000000)) * 1000000000n;
  const z = new Temporal.ZonedDateTime(ns, pick(zones), cal);
  const z2 = z.add({ hours: ri(-20000, 20000) });
  const dt = z.toPlainDateTime();
  const dt2 = z2.toPlainDateTime();
  const d = Temporal.Duration.from({ [pick(['years', 'months', 'weeks', 'days'])]: ri(-30, 30), hours: 0 });
  t(`${i} ${z} fields`, () => [z.year, z.month, z.monthCode, z.day, z.era, z.eraYear, z.hour].join(' '));
  t(`${i} zadd ${d}`, () => z.add(d));
  t(`${i} zuntil ${z2}`, () => z.until(z2, { largestUnit: pick(units), smallestUnit: pick(['day', 'hour', 'minute', 'month']), roundingMode: pick(modes) }));
  t(`${i} dtuntil`, () => dt.until(dt2, { largestUnit: pick(units), smallestUnit: pick(['day', 'hour', 'week', 'month']), roundingMode: pick(modes) }));
  t(`${i} dtadd`, () => dt.add(d));
  t(`${i} zwith`, () => z.with({ month: ri(1, 13), day: ri(1, 30) }));
  t(`${i} dround`, () => d.round({ largestUnit: pick(units), smallestUnit: pick(units), relativeTo: z, roundingMode: pick(modes) }));
  t(`${i} dtotal`, () => d.total({ unit: pick(units), relativeTo: dt }));
  t(`${i} zstr`, () => z.toString({ calendarName: pick(['auto', 'always', 'critical', 'never']) }));
}

